  if (!layout.compact) {
    ctx.fillStyle = "#8b744b"; ctx.font = "700 10px Trebuchet MS, sans-serif";
    ctx.fillText("RECURSOS", x + 128, y + h / 2 + 1);
  }
  ctx.restore();
}

