66:     this.lastUpdateAt = now;
67:     const activePlants = plants.filter((plant) => plant.exists && plant.animationState !== "disappearing");
68: 
69:     for (const enemy of this.enemies.values()) {
70:       if (enemy.state === STATES.DEAD || enemy.state === STATES.DYING || enemy.state === STATES.DAMAGED) continue;
71:       if (enemy.state === STATES.SPAWNING) {
72:         enemy.animation = "spawn";
