15:     this.columns = columns;
16:     this.sun = startingSun;
17:     this.occupancy = Array.from({ length: rows }, () => Array(columns).fill(null));
18:     this.plants = new Map();
19:     this.cardReadyAt = new Map(Object.keys(PLANT_TYPES).map((type) => [type, 0]));
20:     this.nextId = 1;
21:   }
22: 
23:   getPlant(id) { return this.plants.get(id) ?? null; }
24:   getAt(row, column) {
25:     if (!this.isCellInBounds(row, column)) return null;
26:     const id = this.occupancy[row][column];
27:     return id ? this.getPlant(id) : null;
28:   }
29:   isCellInBounds(row, column) {
30:     return Number.isInteger(row) && Number.isInteger(column) &&
31:       row >= 0 && row < this.rows && column >= 0 && column < this.columns;
32:   }
33:   cooldownRemaining(type, now = performance.now()) {
34:     return Math.max(0, (this.cardReadyAt.get(type) ?? 0) - now);
35:   }
36:   canPlace(type, row, column, now = performance.now()) {
37:     const definition = PLANT_TYPES[type];
38:     if (!definition || !this.isCellInBounds(row, column)) return { ok: false, reason: "outside" };
39:     if (this.occupancy[row][column]) return { ok: false, reason: "occupied" };
40:     if (this.sun < definition.cost) return { ok: false, reason: "sun" };
41:     if (this.cooldownRemaining(type, now) > 0) return { ok: false, reason: "cooldown" };
42:     return { ok: true };
43:   }
44:   place(type, row, column, worldPosition, now = performance.now()) {
45:     const check = this.canPlace(type, row, column, now);
46:     if (!check.ok) return check;
47:     const definition = PLANT_TYPES[type];
48:     const id = `plant-${this.nextId++}`;
49:     const plant = {
50:       id,
51:       type,
52:       name: definition.name,
53:       cost: definition.cost,
54:       health: definition.health,
55:       row,
56:       column,
57:       worldPosition: { x: worldPosition.x, y: worldPosition.y },
58:       exists: true,
59:       animationState: "placing",
60:       animationStartedAt: now,
61:       rechargeMs: definition.rechargeMs,
62:     };
63:     this.sun = Math.max(0, this.sun - definition.cost);
64:     this.occupancy[row][column] = id;
65:     this.plants.set(id, plant);
66:     this.cardReadyAt.set(type, now + definition.rechargeMs);
67:     return { ok: true, plant };
68:   }
