70:   remove(id, now = performance.now()) {
71:     const plant = this.getPlant(id);
72:     if (!plant || !plant.exists || plant.animationState === "disappearing") return false;
73:     plant.animationState = "disappearing";
74:     plant.animationStartedAt = now;
75:     return true;
76:   }
77:   update(now = performance.now()) {
78:     for (const [id, plant] of this.plants) {
