22: export function drawPeashooter(ctx, x, y, size, time = 0, options = {}) {
23:   const ghost = Boolean(options.ghost);
24:   const age = Math.max(0, options.age ?? 1000);
25:   const disappearing = Boolean(options.disappearing);
26:   const phase = time * 0.0025;
27:   const breathe = Math.sin(phase) * 1.6;
28:   const leafSwing = Math.sin(phase * 1.35 + 0.8) * 3.2;
29:   let scale = size / 100;
30:   let alpha = ghost ? 0.48 : 1;
31:   if (age < 460 && !ghost) {
32:     const t = Math.max(0, age / 460);
33:     const ease = 1 - Math.pow(1 - t, 3);
34:     scale *= 0.68 + 0.32 * ease;
35:   }
36:   if (disappearing) {
37:     const t = Math.min(1, age / 360);
38:     scale *= 1 - t * 0.34;
39:     alpha *= 1 - t;
40:   }
41:   ctx.save();
