252: function drawProjectile(projectile, time) {
253:   const pulse = 1 + Math.sin((time - projectile.spawnedAt) * .018) * .08;
254:   ctx.save();
255:   ctx.translate(projectile.x, projectile.y);
256:   ctx.shadowColor = "rgba(38,77,25,.35)"; ctx.shadowBlur = 5; ctx.shadowOffsetY = 2;
257:   const glow = ctx.createRadialGradient(-2, -3, 1, 0, 0, projectile.radius * pulse);
258:   glow.addColorStop(0, "#e4ff8a"); glow.addColorStop(.55, "#83d63e"); glow.addColorStop(1, "#438a2c");
259:   ctx.beginPath(); ctx.arc(0, 0, projectile.radius * pulse, 0, Math.PI * 2);
260:   ctx.fillStyle = glow; ctx.fill(); ctx.lineWidth = 1.5; ctx.strokeStyle = "#315d25"; ctx.stroke();
261:   ctx.shadowColor = "transparent";
262:   ctx.beginPath(); ctx.ellipse(-projectile.radius * .3, -projectile.radius * .35, projectile.radius * .22, projectile.radius * .12, -.5, 0, Math.PI * 2);
263:   ctx.fillStyle = "rgba(255,255,220,.8)"; ctx.fill();
264:   ctx.restore();
265: }
