395: function updatePointer(point) {
396:   pointer.x = point.x; pointer.y = point.y; pointer.inside = true;
397:   const { left, top, cellW, cellH, boardW, boardH } = layout;
398:   if (point.x >= left && point.x < left + boardW && point.y >= top && point.y < top + boardH) {
399:     const column = Math.floor((point.x - left) / cellW);
400:     const row = Math.floor((point.y - top) / cellH);
401:     state.hoveredCell = game.isCellInBounds(row, column) ? { row, column } : null;
402:   } else {
403:     state.hoveredCell = null;
404:   }
405: }
