407: function showCardError(type, reason) {
408:   const name = PLANT_TYPES[type]?.name ?? "Planta";
409:   if (reason === "sun") setMessage(`No hay soles suficientes para ${name}.`);
410:   else if (reason === "cooldown") setMessage("La tarjeta todavía está recargando.");
411:   else if (reason === "occupied") setMessage("Esa casilla ya está ocupada.");
412:   else if (reason === "outside") setMessage("Coloca la planta dentro del tablero.");
413: }
