415: function handlePointerUp(event) {
416:   if (pointer.down !== event.button) return;
417:   const button = pointer.down;
418:   pointer.down = null;
419:   const point = canvasPoint(event); updatePointer(point);
420:   if (button === 2) {
421:     const plant = state.hoveredCell && game.getAt(state.hoveredCell.row, state.hoveredCell.column);
422:     if (plant && game.remove(plant.id)) setMessage(`Retirando ${plant.name.toLowerCase()}…`);
423:     return;
424:   }
425:   if (button !== 0) return;
426:   const { x, y, w, h } = layout.card;
427:   if (point.x >= x && point.x <= x + w && point.y >= y && point.y <= y + h) {
428:     const type = "peashooter";
429:     if (state.selected === type) {
430:       state.selected = null;
431:       setMessage("Selección cancelada.");
432:       return;
433:     }
434:     const reason = game.canPlace(type, 0, 0).reason;
435:     if (game.sun < PLANT_TYPES[type].cost) {
436:       showCardError(type, "sun"); state.selected = null; return;
437:     }
438:     if (game.cooldownRemaining(type) > 0) {
439:       showCardError(type, "cooldown"); state.selected = null; return;
440:     }
441:     state.selected = type;
442:     setMessage("Lanzaguisantes elegida: apunta a una casilla libre.");
443:     return;
444:   }
445:   if (!state.hoveredCell) {
446:     if (state.selected) setMessage("Elige una casilla dentro del tablero.");
447:     return;
448:   }
449:   if (!state.selected) {
450:     if (game.getAt(state.hoveredCell.row, state.hoveredCell.column)) setMessage("Esta casilla ya está ocupada.");
451:     return;
452:   }
453:   const cell = state.hoveredCell;
454:   const { left, top, cellW, cellH } = layout;
455:   const worldPosition = {
456:     x: left + (cell.column + .5) * cellW,
457:     y: top + (cell.row + .87) * cellH,
458:   };
459:   const result = game.place(state.selected, cell.row, cell.column, worldPosition);
460:   if (!result.ok) { showCardError(state.selected, result.reason); return; }
461:   state.selected = null;
462:   setMessage(`¡${result.plant.name} plantada!  −${result.plant.cost} soles.`);
463: }
