465: function draw(time) {
466:   game.update(time);
467:   const activePlants = [...game.plants.values()].filter((plant) => plant.alive && plant.exists);
468:   for (const plant of activePlants) plant.boardX = (plant.worldPosition.x - layout.left) / layout.cellW;
469:   enemies.update(time, activePlants, game, layout.cellW);
470:   updateCombat(time);
471:   drawBackground(time);
472:   drawBrand(time);
473:   drawCard(time);
474:   drawCounter();
475:   drawBoard(time);
476:   drawFooter(time);
477:   requestAnimationFrame(draw);
478: }
