480: canvas.addEventListener("pointermove", (event) => updatePointer(canvasPoint(event)));
481: canvas.addEventListener("pointerleave", () => {
482:   if (pointer.down === null) { pointer.inside = false; state.hoveredCell = null; }
483: });
484: canvas.addEventListener("pointerdown", (event) => {
485:   if (event.button !== 0 && event.button !== 2) return;
486:   event.preventDefault(); pointer.down = event.button; updatePointer(canvasPoint(event));
487:   try { canvas.setPointerCapture(event.pointerId); } catch { /* capture can be unavailable in embedded browsers */ }
488: });
